-- ── CMCDM (85건) ─────────────────────────────────────────

MERGE INTO CMCDM T
USING (SELECT 'ALOTPCK' AS CMCDKY, '할당로트피킹준수' AS SHORTX, ' ' AS DBFILD, 'Comply with allocation lot pic' AS USARL1, ' ' AS USARL2, ' ' AS USARL3, ' ' AS USARL4, ' ' AS USARL5, ' ' AS SYONLY, '20250411' AS CREDAT, '93429' AS CRETIM, 'kyh' AS CREUSR, '20250411' AS LMODAT, '93429' AS LMOTIM, 'kyh' AS LMOUSR, ' ' AS INDBZL, ' ' AS INDARC, '0' AS UPDCHK FROM DUAL) S
ON (T.CMCDKY = S.CMCDKY)
WHEN MATCHED THEN
    UPDATE SET T.SHORTX = S.SHORTX, T.DBFILD = S.DBFILD, T.USARL1 = S.USARL1, T.USARL2 = S.USARL2, T.USARL3 = S.USARL3, T.USARL4 = S.USARL4, T.USARL5 = S.USARL5, T.LMODAT = S.LMODAT
WHEN NOT MATCHED THEN
    INSERT (CMCDKY, SHORTX, DBFILD, USARL1, USARL2, USARL3, USARL4, USARL5, SYONLY, CREDAT, CRETIM, CREUSR, LMODAT, LMOTIM, LMOUSR, INDBZL, INDARC, UPDCHK)
    VALUES (S.CMCDKY, S.SHORTX, S.DBFILD, S.USARL1, S.USARL2, S.USARL3, S.USARL4, S.USARL5, S.SYONLY, S.CREDAT, S.CRETIM, S.CREUSR, S.LMODAT, S.LMOTIM, S.LMOUSR, S.INDBZL, S.INDARC, S.UPDCHK);

