    UPDATE SET T.CDESC1 = S.CDESC1, T.CDESC2 = S.CDESC2, T.USARG1 = S.USARG1, T.USARG2 = S.USARG2, T.USARG3 = S.USARG3, T.USARG4 = S.USARG4, T.USARG5 = S.USARG5, T.LMODAT = S.LMODAT
WHEN NOT MATCHED THEN
    INSERT (CMCDKY, CMCDVL, CDESC1, CDESC2, USARG1, USARG2, USARG3, USARG4, USARG5, CREDAT, CRETIM, CREUSR, LMODAT, LMOTIM, LMOUSR, INDBZL, INDARC, UPDCHK)
    VALUES (S.CMCDKY, S.CMCDVL, S.CDESC1, S.CDESC2, S.USARG1, S.USARG2, S.USARG3, S.USARG4, S.USARG5, S.CREDAT, S.CRETIM, S.CREUSR, S.LMODAT, S.LMOTIM, S.LMOUSR, S.INDBZL, S.INDARC, S.UPDCHK);

